"""Refresh the color-transfer palette viewer from retained native/API samples."""
from pathlib import Path
import json,sys
out=Path(sys.argv[1]);transfer=json.loads((out/'transfer.json').read_text());api=json.loads((out/'api-transfer.json').read_text());examples={r['sample']:r for r in api['records'] if r['scale']==2};records=[]
for i,r in enumerate(transfer['samples']):records.append(dict(r,**{k:v for k,v in examples[i].items() if k not in ['id','sample','scale','validation']}))
page='''<!doctype html><meta charset="utf-8"><title>Glass color transfer palette</title><style>body{font:16px/1.5 system-ui;background:#191a1e;color:#eee;margin:24px;max-width:1100px}a{color:#9cf}select{font:inherit}img{width:720px;max-width:100%;display:block;margin:16px 0}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:5px;text-align:left;border-bottom:1px solid #555}.chip{display:inline-block;width:44px;height:24px;vertical-align:middle;border:1px solid #999;margin-right:6px}pre{white-space:pre-wrap}</style><h1>Native color transfer · palette</h1><p><a href="comparison.html">Full tab overlays</a> · <a href="README.md">Method, sources and limits</a></p><p>The native image shows real UITabBars using semantic tints. The table compares actual center pixels with both NXKit foreground APIs. The API test receives the measured native material pixel as its backdrop, so this isolates color blending from material and refraction errors. Green was excluded from fitting. Literal RGB controls remain unchanged in native glass and in NXKit's default path.</p><select id="scene"></select><img id="native" alt="Native UIKit semantic tint palette"><table><thead><tr><th>System tint</th><th>Source</th><th>UIKit pixel</th><th>NX glass</th><th>NX lens</th><th>Mean error /255</th></tr></thead><tbody id="rows"></tbody></table><pre id="details"></pre><script>const data=__DATA__,names=['Blue','Red','Green','Orange','Purple','Mint','Yellow','Indigo','Gray','Teal','Cyan','Pink'],scene=document.getElementById('scene');[...new Set(data.map(r=>r.case))].forEach(c=>scene.add(new Option(c+(c.endsWith('-green')?' (validation)':''),c)));function chip(values){const v=values.map(Math.round);return '<span class="chip" style="background:rgb('+v.join(',')+')"></span>'+v.join(', ')}function update(){const rows=data.filter(r=>r.case===scene.value);document.getElementById('native').src='native/tabs/'+scene.value+'.png';document.getElementById('rows').innerHTML=rows.map(r=>'<tr><td>'+names[r.index]+'</td><td>'+chip(r.source.map(v=>v*255))+'</td><td>'+chip(r.native)+'</td><td>'+chip(r.glass)+'</td><td>'+chip(r.lens)+'</td><td>'+r.lensMAE255.toFixed(2)+'</td></tr>').join('');document.getElementById('details').textContent='Source and material samples are fixed native inputs. No per-frame fitting or pixel registration. '+(rows[0].validation?'Held-out background.':'Calibration background.')};scene.onchange=update;update()</script>'''
(out/'palette.html').write_text(page.replace('__DATA__',json.dumps(records).replace('<','\\u003c')))
p=out/'comparison.html';s=p.read_text().replace('<a href="README.md">Evidence and limits</a>','<a href="README.md">Evidence and limits</a> · <a href="palette.html">12-color native palette</a>');p.write_text(s)
